    public Map<String,Object> grant(String actor,String caseId,Map<String,Object> body){fields(body,"request_id","expected_revision","preparer_username","expires_days","consent");if(!flag(body,"consent"))throw new Problem(400,"EXPLICIT_CASE_SHARING_CONSENT_REQUIRED");long days=number(body,"expires_days");if(days<1||days>30)throw new Problem(400,"SHARING_PERIOD_1_TO_30_DAYS");String login=username(text(body,"preparer_username",3,32));return store.transaction(state->{Map<String,Object> row=owned(state,actor,caseId);var prior=replay(state,actor,body,"grant",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));if(Boolean.TRUE.equals(row.get("archived")))throw new Problem(409,"CASE_ARCHIVED");Map<String,Object> preparer=table(state,"users").values().stream().map(Json::map).filter(u->u.get("username").equals(login)&&u.get("role").equals("PREPARER")&&Boolean.TRUE.equals(u.get("enabled"))).findFirst().orElseThrow(()->new Problem(404,"PREPARER_NOT_FOUND"));Capacity.requireSpace(table(state,"grants"),2000,"LOCAL_GRANT_LIMIT");for(Object raw:table(state,"grants").values()){Map<String,Object> old=Json.map(raw);if(old.get("case_id").equals(caseId)&&old.get("preparer_id").equals(preparer.get("id"))){old.put("active",false);table(state,"grants").put((String)old.get("id"),old);}}
            String grantId=id();table(state,"grants").put(grantId,Map.of("id",grantId,"case_id",caseId,"preparer_id",preparer.get("id"),"preparer_username",login,"purpose","PREPARATION_REVIEW_ONLY","active",true,"created_at",now(),"expires_at",clock.instant().plus(Duration.ofDays(days)).toString(),"credentials_verified",false));row.put("revision",((Number)row.get("revision")).longValue()+1);table(state,"cases").put(caseId,row);audit(state,actor,"PREPARATION_ACCESS_GRANTED",caseId);return receipt(state,actor,body,"grant",caseId,((Number)row.get("revision")).longValue(),"APPLIED");});}
    public Map<String,Object> revoke(String actor,String caseId,Map<String,Object> body){fields(body,"request_id","expected_revision","grant_id");return store.transaction(state->{Map<String,Object> row=owned(state,actor,caseId);var prior=replay(state,actor,body,"revoke",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));String grantId=text(body,"grant_id",1,64);Object raw=table(state,"grants").get(grantId);if(raw==null||!Json.map(raw).get("case_id").equals(caseId))throw new Problem(404,"GRANT_NOT_FOUND");Map<String,Object> grant=Json.map(raw);grant.put("active",false);table(state,"grants").put(grantId,grant);row.put("revision",((Number)row.get("revision")).longValue()+1);table(state,"cases").put(caseId,row);audit(state,actor,"PREPARATION_ACCESS_REVOKED",caseId);return receipt(state,actor,body,"revoke",caseId,((Number)row.get("revision")).longValue(),"APPLIED");});}
    public Map<String,Object> note(String actor,String caseId,Map<String,Object> body){fields(body,"request_id","expected_revision","text");String note=text(body,"text",1,1000);return store.transaction(state->{Map<String,Object> u=user(state,actor);Object raw=table(state,"cases").get(caseId);if(raw==null||!allowedReview(state,actor,Json.map(raw)))throw new Problem(404,"CASE_NOT_FOUND");Map<String,Object> row=Json.map(raw);var prior=replay(state,actor,body,"note",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));if(Boolean.TRUE.equals(row.get("archived")))throw new Problem(409,"CASE_ARCHIVED");List<Object> notes=Json.list(row.get("preparation_notes"));if(notes.size()>=50)throw new Problem(409,"NOTE_LIMIT");notes.add(Map.of("id",id(),"author",u.get("display_name"),"text",note,"input_snapshot",row.get("snapshot"),"at",now(),"scope","PREPARATION_COMMENT_NOT_CA_SIGNOFF"));row.put("preparation_notes",notes);row.put("revision",((Number)row.get("revision")).longValue()+1);row.put("updated_at",now());table(state,"cases").put(caseId,row);audit(state,actor,"PREPARATION_COMMENT_ADDED",caseId);return receipt(state,actor,body,"note",caseId,((Number)row.get("revision")).longValue(),"APPLIED");});}
    public List<Map<String,Object>> prices(){return store.read(state->table(state,"prices").values().stream().map(Json::map).sorted((a,b)->((String)b.get("created_at")).compareTo((String)a.get("created_at"))).toList());}
    public Map<String,Object> publishPrice(String actor,Map<String,Object> body){fields(body,"request_id","plan","amount_paise","effective_at","label");String plan=text(body,"plan",1,24),label=text(body,"label",1,80);if(!Set.of("GUIDED_PREPARATION","FIRM_WORKSPACE").contains(plan))throw new Problem(400,"INVALID_PLAN");long price=number(body,"amount_paise");if(price>10_000_000)throw new Problem(400,"PRICE_ABOVE_LOCAL_LIMIT");Instant effective;try{effective=Instant.parse(text(body,"effective_at",1,40));}catch(java.time.format.DateTimeParseException e){throw new Problem(400,"INVALID_EFFECTIVE_DATE");}if(effective.isBefore(clock.instant()))throw new Problem(400,"PRICE_MUST_START_IN_FUTURE");return store.transaction(state->{role(user(state,actor),"ADMIN");var prior=replay(state,actor,body,"price",null);if(prior!=null)return prior;Map<String,Object> prices=table(state,"prices");Capacity.requireSpace(prices,200,"PRICE_VERSION_LIMIT");if(prices.values().stream().map(Json::map).anyMatch(p->p.get("plan").equals(plan)&&p.get("effective_at").equals(effective.toString())))throw new Problem(409,"DUPLICATE_EFFECTIVE_PRICE");String priceId=id();long version=prices.values().stream().map(Json::map).filter(p->p.get("plan").equals(plan)).count()+1;prices.put(priceId,Map.of("id",priceId,"version",version,"plan",plan,"label",label,"amount_paise",price,"currency","INR","effective_at",effective.toString(),"created_at",now(),"sale_status","PLANNING_QUOTE_ONLY"));audit(state,actor,"FUTURE_PRICE_VERSION_CREATED",priceId);return receipt(state,actor,body,"price",priceId,version,"APPLIED");});}
    public Map<String,Object> quote(String actor,Map<String,Object> body){fields(body,"request_id","plan");String plan=text(body,"plan",1,24);return store.transaction(state->{user(state,actor);var prior=replay(state,actor,body,"quote",null);if(prior!=null)return prior;Capacity.requireSpace(table(state,"quotes"),2000,"LOCAL_QUOTE_LIMIT");Map<String,Object> price=table(state,"prices").values().stream().map(Json::map).filter(p->p.get("plan").equals(plan)&&!clock.instant().isBefore(Instant.parse((String)p.get("effective_at")))).max((a,b)->((String)a.get("effective_at")).compareTo((String)b.get("effective_at"))).orElseThrow(()->new Problem(409,"NO_ACTIVE_PRICE"));String quoteId=id();Map<String,Object> q=new LinkedHashMap<>();q.put("id",quoteId);q.put("owner_id",actor);q.put("plan",plan);q.put("price_version_id",price.get("id"));q.put("price_version",price.get("version"));q.put("amount_paise",price.get("amount_paise"));q.put("currency","INR");q.put("issued_at",now());q.put("expires_at",clock.instant().plus(Duration.ofHours(24)).toString());q.put("status","QUOTE_ONLY_PAYMENT_NOT_CONNECTED");q.put("payment_available",false);q.put("tax_capability_changed",false);table(state,"quotes").put(quoteId,q);audit(state,actor,"PLANNING_QUOTE_ISSUED",quoteId);return receipt(state,actor,body,"quote",quoteId,1L,"APPLIED");});}
