    public Map<String,Object> openTicket(String actor,Map<String,Object> body){fields(body,"request_id","topic","subject","message");String topic=text(body,"topic",1,32),subject=text(body,"subject",1,100),message=text(body,"message",1,1000);if(!Set.of("PRODUCT_HELP","DATA_REQUEST","VALIDATION_QUESTION","BILLING_QUESTION").contains(topic))throw new Problem(400,"INVALID_SUPPORT_TOPIC");return store.transaction(state->{user(state,actor);var prior=replay(state,actor,body,"ticket",null);if(prior!=null)return prior;Capacity.requireSpace(table(state,"tickets"),2000,"LOCAL_TICKET_LIMIT");String ticketId=id();table(state,"tickets").put(ticketId,Map.of("id",ticketId,"owner_id",actor,"topic",topic,"subject",subject,"status","OPEN","revision",1L,"created_at",now(),"messages",List.of(Map.of("text",message,"sender","CUSTOMER","at",now()))));audit(state,actor,"SUPPORT_REQUEST_OPENED",ticketId);return receipt(state,actor,body,"ticket",ticketId,1L,"APPLIED");});}
    public List<Map<String,Object>> tickets(String actor){return store.read(state->{Map<String,Object> u=user(state,actor);return table(state,"tickets").values().stream().map(Json::map).filter(t->t.get("owner_id").equals(actor)||u.get("role").equals("ADMIN")).toList();});}
    public Map<String,Object> updateTicket(String actor,String ticketId,Map<String,Object> body){fields(body,"request_id","expected_revision","status","message");String status=text(body,"status",1,20),message=text(body,"message",0,1000);if(!Set.of("OPEN","RESOLVED").contains(status))throw new Problem(400,"INVALID_TICKET_STATUS");return store.transaction(state->{Map<String,Object> u=user(state,actor);Object raw=table(state,"tickets").get(ticketId);if(raw==null)throw new Problem(404,"TICKET_NOT_FOUND");Map<String,Object> ticket=Json.map(raw);if(!ticket.get("owner_id").equals(actor)&&!u.get("role").equals("ADMIN"))throw new Problem(404,"TICKET_NOT_FOUND");var prior=replay(state,actor,body,"ticket-update",ticketId);if(prior!=null)return prior;revision(ticket,number(body,"expected_revision"));List<Object> messages=Json.list(ticket.get("messages"));if(!message.isBlank()){if(messages.size()>=30)throw new Problem(409,"TICKET_MESSAGE_LIMIT");messages.add(Map.of("text",message,"sender",u.get("role").equals("ADMIN")?"SUPPORT":"CUSTOMER","at",now()));}ticket.put("messages",messages);ticket.put("status",status);ticket.put("revision",((Number)ticket.get("revision")).longValue()+1);table(state,"tickets").put(ticketId,ticket);audit(state,actor,"SUPPORT_REQUEST_UPDATED",ticketId);return receipt(state,actor,body,"ticket-update",ticketId,((Number)ticket.get("revision")).longValue(),"APPLIED");});}
