    public Map<String,Object> gst(String actor,String caseId){return store.read(state->{Map<String,Object> row=owned(state,actor,caseId);return GstReconciliation.projection(tool(row,"gst"));});}
    public Map<String,Object> gstCommand(String actor,String caseId,Map<String,Object> body){
        String operation=text(body,"operation",1,16);Set<String> extra=switch(operation){case "IMPORT"->Set.of("period","books_csv","statement_csv","same_entity_confirmed","books_complete","statement_complete");case "REVIEW"->Set.of("worksheet_version","group_id","action","observations_reviewed");case "CLEAR"->Set.of();default->throw new Problem(400,"GST_UNKNOWN_OPERATION");};Set<String> expected=new java.util.HashSet<>(Set.of("operation","request_id","expected_revision"));expected.addAll(extra);if(!expected.equals(body.keySet()))throw new Problem(400,"UNEXPECTED_FIELDS");
        return store.transaction(state->{Map<String,Object> row=owned(state,actor,caseId);var prior=replay(state,actor,body,"gst",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));if(Boolean.TRUE.equals(row.get("archived")))throw new Problem(409,"CASE_ARCHIVED");Map<String,Object> preparation=tools(row);
            switch(operation){
                case "IMPORT"->{String period=GstReconciliation.period(text(body,"period",7,7)),books=text(body,"books_csv",1,20000),statement=text(body,"statement_csv",1,20000);GstReconciliation.parse(books,false);GstReconciliation.parse(statement,true);Map<String,Object> sheet=new LinkedHashMap<>();sheet.put("version",id());sheet.put("period",period);sheet.put("books_csv",books);sheet.put("statement_csv",statement);sheet.put("decisions",new LinkedHashMap<>());for(String k:List.of("same_entity_confirmed","books_complete","statement_complete"))sheet.put(k,flag(body,k));preparation.put("gst",sheet);}
                case "REVIEW"->{Map<String,Object> sheet=tool(row,"gst");GstReconciliation.review(sheet,body);preparation.put("gst",sheet);}
                case "CLEAR"->preparation.remove("gst");
                default->throw new IllegalStateException("unhandled GST operation");
            }
            row.put("self_service",preparation);return savePreparation(state,actor,row,body,"gst","GST_"+operation);
        });
    }
    private Map<String,Object> savePreparation(Map<String,Object> state,String actor,Map<String,Object> row,Map<String,Object> body,String route,String action){long version=((Number)row.get("revision")).longValue()+1;row.put("revision",version);row.put("updated_at",now());String caseId=(String)row.get("id");table(state,"cases").put(caseId,row);audit(state,actor,action,caseId);return receipt(state,actor,body,route,caseId,version,"APPLIED");}
