    public Map<String,Object> workbenchCommand(String actor,String caseId,Map<String,Object> body){
        TaxWorkbench.validateFields(body);
        return store.transaction(state->{Map<String,Object> row=owned(state,actor,caseId);var prior=replay(state,actor,body,"tax-workbench",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));if(Boolean.TRUE.equals(row.get("archived")))throw new Problem(409,"CASE_ARCHIVED");boolean material=TaxWorkbench.apply(row,body,clock);
            if(material){row.put("snapshot",id());row.put("reviews",reviews());if(((String)body.get("operation")).startsWith("CAPITAL_")){Map<String,Object> profile=Json.map(row.get("profile"));profile.put("screen_special","UNKNOWN");profile.put("profile_confirmed","NO");profile.put("eligible_confirmed","NO");row.put("profile",profile);}}
            if(Json.bytes(row).length>240000)throw new Problem(409,"CASE_RECORD_SIZE_LIMIT");return savePreparation(state,actor,row,body,"tax-workbench",(String)body.get("operation"));});
    }
