    public Map<String,Object> proposeNative(String actor,String caseId,Map<String,Object> body,java.util.function.Supplier<NativeImports.Preview> source){
        fields(body,"request_id","expected_revision","preview_id","same_taxpayer_confirmed","selections");text(body,"preview_id",43,43);List<Object> selections=Json.list(body.get("selections"));if(selections.isEmpty()||selections.size()>4)throw new Problem(400,"NATIVE_SELECT_1_TO_4_FIELDS");
        return store.transaction(state->{Map<String,Object> row=owned(state,actor,caseId);var prior=replay(state,actor,body,"native-propose",caseId);if(prior!=null)return prior;revision(row,number(body,"expected_revision"));if(Boolean.TRUE.equals(row.get("archived")))throw new Problem(409,"CASE_ARCHIVED");if(!flag(body,"same_taxpayer_confirmed"))throw new Problem(409,"NATIVE_SAME_TAXPAYER_REVIEW_REQUIRED");NativeImports.Preview preview=source.get();
            if(!preview.actor().equals(actor)||!preview.caseId().equals(caseId)||preview.revision()!=((Number)row.get("revision")).longValue())throw new Problem(409,"STALE_NATIVE_PREVIEW");
            Map<String,Object> inputs=Json.map(row.get("inputs")),links=Json.map(row.get("source_links")),nativeLinks=row.containsKey("native_import_links")?Json.map(row.get("native_import_links")):new LinkedHashMap<>();Set<String> selected=new java.util.HashSet<>();
            for(Object raw:selections){Map<String,Object> selection=Json.map(raw);fields(selection,"field","amount","whole_category_confirmed","replace_input_confirmed");String field=text(selection,"field",1,32);NativeImports.Proposal offered=preview.proposals().get(field);if(offered==null||!selected.add(field))throw new Problem(409,"NATIVE_FIELD_NOT_OFFERED");if(!offered.amount().equals(text(selection,"amount",1,16)))throw new Problem(409,"DISPLAYED_AMOUNT_CHANGED");if(!flag(selection,"whole_category_confirmed"))throw new Problem(409,"WHOLE_CATEGORY_REVIEW_REQUIRED");if(!flag(selection,"replace_input_confirmed"))throw new Problem(409,"REPLACEMENT_REVIEW_REQUIRED");
                inputs.put(field,Map.of("state","ESTIMATED","amount",offered.amount()));links.remove(field);nativeLinks.put(field,Map.of("schema_id",NativeImports.SCHEMA_ID,"schema_sha256",NativeImports.SCHEMA_SHA,"source_path",offered.sourcePath(),"source_authenticity","NOT_VERIFIED","proposal_only",true));
            }
            row.put("inputs",inputs);row.put("source_links",links);row.put("native_import_links",nativeLinks);row.put("snapshot",id());row.put("reviews",reviews());row.put("revision",((Number)row.get("revision")).longValue()+1);row.put("updated_at",now());table(state,"cases").put(caseId,row);audit(state,actor,"NATIVE_INCOME_PROPOSED",caseId);return receipt(state,actor,body,"native-propose",caseId,((Number)row.get("revision")).longValue(),"APPLIED");
        });
    }
